    {
        new FieldMetadata(FieldIds.Dance, "Dance", "Which social dances a track serves on the floor — the danceability axis, distinct from the musical 'genre' it belongs to and from the listening-situation 'theme'. A track may serve several dances at once, and order carries meaning: the first entry is the primary/headline dance and the entry count is the track's versatility, which is why there is no separate primary_dance or dance_versatility field. (The legacy MediaMonkey 'Occasion' column is a misnomer for this field, not a separate concept.)", "Filter the library into per-dance pools and build for the room in front of you — 'give me Lindy at 180', 'a blues set'.", "taxonomy-core-a", "taxonomy", "dances"),
        new FieldMetadata(FieldIds.Genre, "Genre", "The musicological style(s) of the recording — the coarse musical bucket a DJ reasons about before tempo and feel. It captures what the music IS, not whether it is danceable: the same Swing record may suit Lindy, Balboa, or neither depending on the tempo and feel fields, so genre seeds dance and era expectations but never decides them alone.", "Reason about a track's era/character, seed dance + mood expectations, and build style-coherent or deliberately-contrasting blocks.", "taxonomy-core-a", "taxonomy", "genre"),
        new FieldMetadata(FieldIds.Mood, "Mood", "The track's emotional feel, placed on the vocabulary's Energy × Valence mood model. Unlike the standalone energy field (raw floor-drive) or theme (listening/event situation), mood is the valence-aware affect descriptor — what the record sounds like emotionally, not just how hard it pushes the room.", "Steer the room's affect — pull a lift, a cool-down, or a peak by feel, and avoid jarring valence jumps.", "taxonomy-core-a", "taxonomy", "mood"),
        new FieldMetadata(FieldIds.Vocality, "Vocality", "Captures whether anyone sings and in what role — instrumental versus a lead singer, an ensemble vocal, an occasional vocal feature over an otherwise instrumental track, or non-lyric voice like scat or spoken word — including the singer's gender where it applies. It describes the presence and character of the voice, not the words sung (lyric language is a separate field).", "Alternate instrumental vs vocal and male vs female leads for variety; pull instrumentals for classes/jams or vocals to draw the crowd.", "taxonomy-core-a", "taxonomy", "vocality"),
        new FieldMetadata(FieldIds.RhythmicFeel, "Rhythmic Feel", "The dominant rhythmic groove a dancer locks into — the pre-tempo axis (swung vs straight vs shuffle vs slow-drag) that separates two records at the same BPM and genre into different dances and floor energies. It is finer-grained than meter: meter only gates the beats-per-bar grouping, while feel captures the subdivision and accent character within that grouping.", "Hold or deliberately switch the groove (shuffle vs straight vs slow-drag) — the main blues flow lever beyond tempo.", "taxonomy-core-a", "taxonomy", "rhythmic_feel"),
        new FieldMetadata(FieldIds.Instrumentation, "Instrumentation (Ensemble)", "The performing-ensemble format of the recording — its size tier (solo through large) and idiom. Distinct from instrument_led (which lead voice carries the track) and vocality (presence and gender of vocals): instrumentation is about the shape and weight of the whole group, not who fronts it or whether anyone sings.", "Balance big-band 'meat' against small-combo texture and alternate ensemble size for variety.", "taxonomy-core-b", "taxonomy", "instrumentation"),
        new FieldMetadata(FieldIds.InstrumentLed, "Instrument-Led", "The instrument(s) that carry or feature on the track — the lead voice(s), not the full instrument roster. Name a specific instrument when one dominates, or a generic family when no single instrument leads.", "Spot or avoid clustering similar-sounding lead instruments across a block.", "taxonomy-core-b", "taxonomy", "instrument"),
        new FieldMetadata(FieldIds.RecordingContext, "Recording Context", "How the recording was captured — its performance setting and provenance (studio session, live concert, radio/broadcast, film soundtrack, bootleg, jam, transcription disc). Distinct from recording_quality_era, which is the technology/fidelity window, and from TDRC, which is the precise release year.", "Avoid dropping a talky live/applause track where you need a tight transition; choose studio vs live deliberately.", "taxonomy-core-b", "taxonomy", "recording_context"),
        new FieldMetadata(FieldIds.Theme, "Theme (Listening / Event Context)", "The listening, event, or seasonal occasion a track suits (Christmas, Cocktail, Heartbreak, Late Night) — the situation a DJ programs for, beyond the track's musical identity. Distinct from Mood, which is the emotional feel: Theme=Love is the lyric topic while Mood=Tender is the feel; Theme=Driving is in-car listening while Mood=Driving is rhythmic motor. Also distinct from the dance/occasion side — listening-context themes are not dance-floor markers.", "Pull a holiday / Valentine / Halloween / event set on demand.", "taxonomy-core-b", "taxonomy", "theme"),
        new FieldMetadata(FieldIds.RecordingQualityEra, "Recording Quality Era", "The recording-technology window a track was captured in, which sets its inherent fidelity ceiling — frequency range, mono vs stereo, surface noise. It describes the source's sonic character, not how good a particular copy is; a clean reissue master of an old acoustic cut still carries acoustic-era character.", "Rank duplicate versions and judge whether a lo-fi acoustic-era recording suits the room and PA.", "taxonomy-core-b", "taxonomy", "recording_quality_era"),
        new FieldMetadata(FieldIds.SongForm, "Song Form", "The harmonic/structural form of a single chorus (12-bar blues, 32-bar AABA, multi-strain ragtime, etc.). This is the repeating chord-and-section template only — it does not capture where individual breaks or phrases land in this particular recording, nor any positional beat-by-beat annotation; those positional details are a separate, private concern.", "Know the harmonic form (AABA / 12-bar) for routine matching and musicality cueing.", "taxonomy-core-b", "taxonomy", "song_form"),
        new FieldMetadata(FieldIds.Bpm, "BPM (raw)", "The raw machine-measured beats-per-minute of the track, written as an integer to the standard TBPM frame. It is the literal pulse rate from the beat grid, NOT the tempo a dancer perceives — half/double-time tracks carry their raw value here (set it to the danced pulse if your detector mis-locks on a subdivision). Auto-derivable from the SB-Beats cache; once a user confirms it the BPM confirmation gate (Custom10) protects it.", "The primary set-building filter — find tracks inside the dance's tempo window.", "measured-confirmation", "measured", null),
        new FieldMetadata(FieldIds.Rating, "Rating", "The DJ's quality/usability rating of the track on a 0-5 scale in half-star increments. Internally carried as half-stars; on disk it is a single POPM popularity byte under owner 'no@email' so MediaMonkey and JRiver read the same stars. It is a workflow judgement (is this track worth playing), distinct from danceability or energy.", "Your fastest trust signal mid-set — 'which of my 150-BPM tracks is actually a killer'.", "measured-confirmation", "measured", null),
        new FieldMetadata(FieldIds.ConfirmationGates, "Confirmation gates (Custom10)", "Per-category ledger of which logical fields the user has hand-verified, forming the trust boundary that protects curated values from automated overwrites. The reference implementation reads it before touching a gated field: heuristic auto-corrections (BPM half-time fix, alias normalization) must refuse the write unless the caller explicitly forces a re-analyze, and a merge/bulk edit that genuinely changes a field clears that field's gate (audio-derived gates are preserved since their inputs aren't merged).", "Lock human-verified fields so auto-suggestions / re-analysis don't overwrite your confirmed calls.", "measured-confirmation", "confirmation", null),
        new FieldMetadata(FieldIds.SdtsVersion, "SDTS schema version", "The SDTS schema version the file was last written / normalized under. On load the toolkit compares it to the current version: older -> run the relevant migrations and re-normalize; equal -> skip. Makes normalization cheap and idempotent. Distinct from SB-Migrations (one-shot per-migration tokens) — this is the single 'where is this file at' watermark.", "Skip files already at the current standard and migrate only older ones — fast, idempotent normalization.", "measured-confirmation", "meta", null),
        new FieldMetadata(FieldIds.Energy, "Energy", "A standalone 1-10 floor-drive rating, independent of both BPM and the mood's valence. Captures how hard a track pushes the room: a slow grinding blues can be energy 8 at 70 BPM; a bright mid-tempo novelty can be energy 3. Decouples the 'how much does this lift the floor' lever from the energy×valence mood grid, which is too coarse (only high/medium/low and always tied to brightness).", "Build the night's energy arc and contrast — pull an opener, a builder, a peak, a cool-down.", "proposed-tempo-structure", "measured", null),
        new FieldMetadata(FieldIds.Valence, "Valence", "A standalone 1-10 brightness rating — the valence half of the energy × valence pair, carried as its own field exactly as energy is. Captures how dark or bright the record reads: a driving minor-key stomp can be energy 8 / valence 3, a gentle sunny ballad energy 3 / valence 8. Independent of BPM and of which moods are tagged.", "Pick by brightness independently of drive — a dark peak, a bright cool-down — and avoid jarring valence jumps between records.", "proposed-tempo-structure", "measured", null),
        new FieldMetadata(FieldIds.TempoStability, "Tempo Stability", "A one-word summary of how steady the pulse is across the track, derived from the variance of the SB-Beats inter-beat intervals. 'stable' tracks are safe for back-to-back mixing; 'rubato'/'accelerando'/'tempo-change' warn the DJ of a moving target that may strand dancers or break a transition.", "Avoid rubato / tempo-change tracks when you need a steady, beatmatchable floor.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.Meter, "Meter", "The meter of the track — either the full time signature OR just the beats-per-bar grouping (2/3/4) when you do not know or do not care about the denominator. Makes it a hard gate: only a 3-feel (3, 3/4, 3/8) qualifies for Waltz (#WLZ) / Tango-Vals (#TGW); the rest is a 2- or 4-feel. Triplet vs straight (e.g. 12/8 vs 4/4) is rhythmic_feel's job.", "Gate 3/4 waltz-family material apart from 4/4.", "proposed-tempo-structure", "taxonomy", null),
        new FieldMetadata(FieldIds.IntroDuration, "Intro Duration", "How long the intro runs before the danceable groove lands, in ms. DESCRIPTIVE — not a trim instruction (that is playback_start) — so the editor/player can flag a long talky/rubato/count-in intro. Auto-derivable from the beat grid (time to the first strong downbeat).", "Spot tracks with an uncomfortably long intro before the groove.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.OutroDuration, "Outro Duration", "How long the outro/tail runs after the last danceable groove, in ms. DESCRIPTIVE — not a trim instruction (that is playback_stop) — so the editor/player can flag a long fade or applause tail. Pairs with ending_type. Auto-derivable from the beat grid and segment boundaries.", "Spot tracks with a long fade / applause tail.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.EndingType, "Ending Type", "How the track ends — a definitive resolved ending, a fade-out, or a cold stop. The genuinely distinct part of the old intro_outro composite: lets the editor flag fade/cold-stop endings that hurt social-dance flow and the player time transitions.", "Know the ending (definitive / fade / cold-stop) for tight transitions.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.PlaybackStart, "Playback Start (cue-in)", "The point (ms from the start of the file) where playback should begin — the cue-in. Trims dead air, a long count-in, or a rubato/spoken intro so the danceable part starts immediately. Absent or 0 means start at the beginning. Distinct from intro_duration, which only *describes* the intro length; playback_start is the actual instruction to skip it. (JRiver expresses the pair as one string field [Playback Range] = \"cue-in - cue-out\"; SDTS uses two scalars for easier validation.)", "Skip a long talky / applause / rubato intro so the track drops straight into the groove.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.PlaybackStop, "Playback Stop (cue-out)", "The point (ms) where playback should stop — the cue-out. Cuts a long fade-out, an applause tail, or hidden-track silence so the next track comes in cleanly. Absent means play to the end. Pairs with playback_start as the portable equivalent of JRiver [Playback Range] / iTunes Stop Time.", "Cut a fade-out or applause tail so the next track comes in tight.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.FadeInDuration, "Fade-in", "Length of a fade-in ramp applied from playback_start (the cue-in). 0 or absent = hard entry (no fade). Lets a track ease in from its chosen cue point instead of jumping in. The fade CURVE is not stored — the player picks it (default equal-power); add a fade_curve field only if some track needs a non-default shape.", "Ease a track in from its cue-in instead of a hard entry.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.FadeOutDuration, "Fade-out", "Length of a fade-out ramp that ENDS at playback_stop (the cue-out). 0 or absent = cold stop. Your example — end at 200 s with a 2 s fade — is playback_stop=200000, fade_out_duration=2000 (clean, no '+'-as-arithmetic ambiguity). Curve not stored; player default equal-power.", "Tame a fade-ending or applause-tailed record with a clean fade.", "proposed-tempo-structure", "derived", null),
        new FieldMetadata(FieldIds.Routine, "Routine", "Names the choreographed line routines (Shim Sham, Tranky Doo, Big Apple, Jitterbug Stroll) that this exact recording serves, and how well it fits each. Genre, mood, BPM, and even the dance tag only say a track fits the style; this field says THIS specific recording is the one the routine is actually danced to — whether the original accompaniment, an accepted substitute, or an experimental stretch.", "Pull THE Shim Sham / Big Apple / Tranky Doo track (original), with vetted alternatives and experimental options behind it.", "proposed-dance-semantic", "taxonomy", "routine"),
        new FieldMetadata(FieldIds.Danceability, "Danceability", "A 1–10 beat-clarity / floor-readiness score answering \"is this danceable, or is it a listening track?\" — the single dimension DJ guides rank above genre and BPM. It decouples \"good music\" from \"good FLOOR music\": a beloved torch ballad can be a 2, an average jump tune a 5. Auto-derivable as a first pass from beat-grid pulse strength in the SB-Beats cache, then human-confirmed (gate-able).", "Separate genuine floor tracks from listening-only music.", "proposed-dance-semantic", "measured", null),
        new FieldMetadata(FieldIds.LyricLanguage, "Lyric Language", "The language(s) of the sung or spoken words, the lyric language a DJ screens for crowd comprehension and sing-along sets. This is the content language of the words themselves, not the language tagged on the recording's metadata. Where Vocality captures the presence and type of voice, this captures what tongue that voice is in.", "Filter by sung language for language-specific rooms or sing-along sets.", "proposed-content-provenance", "taxonomy", null),
        new FieldMetadata(FieldIds.RecordingOrigin, "Recording Origin", "Where a recording sits on the authenticity/provenance axis relative to the music's own era — an original-era cut, a modern band playing the idiom period-correctly, or a re-release of an original. Deliberately orthogonal to the three sibling axes it is easily confused with: release year (when the music was written/popularized), recording quality / quality-era (how it sounds, e.g. Acoustic vs Digital Era), and recording context (the capture setting, Studio/Live/Broadcast). A 2015 digital-era faithful revival of a 1936 Lindy tune scores on all three independently, which is why provenance needs its own field.", "Choose period-original vs revival/cover vs reissue — Herrang wants vintage, a modern crowd may prefer a clean revival.", "proposed-content-provenance", "taxonomy", null),
        new FieldMetadata(FieldIds.OriginalTitle, "Original Title", "The title of the WORK this recording performs, when it differs from this recording's own title (TIT2). It is the missing fourth member of the original-work cluster: TOPE carries the original performer, TOAL the original album, TDOR the original date — and until now nothing carried the original TITLE, a gap TIT2's own documentation names. Absent on an original-era recording, exactly like TOPE.", "Group performances of one work — pull every version of 'Stormy Monday', or avoid programming the same work twice in a set.", "proposed-content-provenance", "taxonomy", null),
        new FieldMetadata(FieldIds.ArtistCountry, "Artist Country", "The country the artist or music ORIGINATES from (France for Django Reinhardt, the United States for Count Basie), so a DJ can build country- or region-themed sets like a French Manouche night or a US-only block. This is about origin, not where a release was issued (release-country) or where the track was recorded (recording-location).", "Pull a country / region set — 'only French', 'US-only' — for geographic theming.", "proposed-content-provenance", "taxonomy", null),
        new FieldMetadata(FieldIds.Regions, "Regions", "Manually-marked typed regions on a track — leading/trailing silence, spoken/speech passages, and music-boundary marks — persisted durably in-tag so they survive across sessions and machines. Each region is a [start_ms, end_ms) span with a kind (silence/speech/music-boundary). Distinct from playback_start/stop (single cue points) and intro/outro_duration (scalar lengths): regions is the general list of typed spans.", "Trim talky intros, mark silence gaps, flag music-vs-speech boundaries — durable across machines.", "proposed-tempo-structure", "derived", null),
